import { formatName } from "./names";

export interface Greeting {
  text: string;
  locale: string;
}

export function greet(name: string): Greeting {
  const text = "Hello, " + formatName(name);
  return { text, locale: "en" };
}

export function farewell(name: string): string {
  return "Bye, " + formatName(name);
}

export function shout(name: string): string {
  return greet(name).text.toUpperCase();
}

export function whisper(name: string): string {
  return greet(name).text.toLowerCase();
}

export function repeat(name: string, times: number): string {
  return Array.from({ length: times }, () => greet(name).text).join(" ");
}

export const DEFAULT_LOCALE = "en";

